 */

import {execSync, type ExecSyncOptionsWithStringEncoding} from 'child_process';
import path from 'path';
import query from 'querystring';
import _ from 'lodash';
import detect from 'detect-port';
import prompts from 'prompts';
import logger from '@docusaurus/logger';
import {matchRoutes as reactRouterMatchRoutes} from 'react-router-config';
import {
  parseURLPath,
  serializeURLPath,
  flattenRoutes,
  DEFAULT_PARSE_FRONT_MATTER,
  DEFAULT_STATIC_DIR_NAME,
  DEFAULT_I18N_DIR_NAME,
  DEFAULT_PORT,
  docuHash,
  simpleHash,
  escapePath,
  generate,
  type URLPath,
} from '@docusaurus/utils';
import {
  addTrailingSlash,
  addLeadingSlash,
  removeTrailingSlash,
  applyTrailingSlash,
  type ApplyTrailingSlashParams,
} from '@docusaurus/utils-common';
import {Joi, printWarning} from '@docusaurus/utils-validation';
import htmlTags from 'html-tags';
import voidHtmlTags from 'html-tags/void';
import escapeHTML from 'escape-html';
import type {FutureConfig, StorageConfig} from '@docusaurus/types/src/config';
import type {
  RouteConfig,
  ReportingSeverity,
  DocusaurusConfig,
  I18nConfig,
  MarkdownConfig,
  Module,
  RouteModules,
  ChunkNames,
  RouteChunkNames,
  PluginRouteConfig,
  PluginIdentifier,
  Props,
  HtmlTagObject,
  HtmlTags,
  LoadedPlugin,
} from '@docusaurus/types';

function matchRoutes(routeConfig: RouteConfig[], pathname: string) {
  // @ts-expect-error: React router types RouteConfig with an actual React
  // component, but we load route components with string paths.
  // We don't actually access component here, so it's fine.
  return reactRouterMatchRoutes(routeConfig, pathname);
}

type BrokenLink = {
  link: string;
  resolvedLink: string;
  anchor: boolean;
};

type BrokenLinksMap = {[pathname: string]: BrokenLink[]};

type CollectedLinks = {
  [pathname: string]: {links: string[]; anchors: string[]};
};

type CollectedLinksNormalized = Map<
  string,
  {links: Set<string>; anchors: Set<string>}
>;

type RoutesCode = {
  routesConfig: string;
  routesChunkNames: RouteChunkNames;
  registry: {
    [chunkName: string]: string;
  };
};

type GenerateRouteFilesParams = {
  generatedFilesDir: string;
  routes: PluginRouteConfig[];
  baseUrl: string;
};

type HostPortOptions = {
  host?: string;
  port?: string;
};

type BrokenLinkState = {
  collectedLinks: CollectedLinksNormalized;
  validPathnames: Set<string>;
  remainingRoutes: RouteConfig[];
  routes: RouteConfig[];
  brokenLinks: BrokenLinksMap;
  brokenPaths: BrokenLinksMap;
  brokenAnchors: BrokenLinksMap;
  onBrokenLinks: ReportingSeverity;
  onBrokenAnchors: ReportingSeverity;
};

type ConfigState = {
  defaultI18nConfig: I18nConfig;
  defaultStorageConfig: StorageConfig;
  defaultFutureConfig: FutureConfig;
  defaultMarkdownConfig: MarkdownConfig;
  defaultConfig: Pick<
    DocusaurusConfig,
    | 'i18n'
    | 'future'
    | 'onBrokenLinks'
    | 'onBrokenAnchors'
    | 'onBrokenMarkdownLinks'
    | 'onDuplicateRoutes'
    | 'plugins'
    | 'themes'
    | 'presets'
    | 'headTags'
    | 'stylesheets'
    | 'scripts'
    | 'clientModules'
    | 'customFields'
    | 'themeConfig'
    | 'titleDelimiter'
    | 'noIndex'
    | 'tagline'
    | 'baseUrlIssueBanner'
    | 'staticDirectories'
    | 'markdown'
  >;
  pluginSchema: unknown;
  themeSchema: unknown;
  presetSchema: unknown;
  localeConfigSchema: unknown;
  i18nConfigSchema: unknown;
  storageConfigSchema: unknown;
  futureConfigSchema: unknown;
  siteUrlSchema: unknown;
  configSchema: ReturnType<typeof Joi.object>;
  siteConfigPath: string;
  lastValidatedConfig: DocusaurusConfig | null;
  unknownFields: string;
  formattedError: string;
};

type HostPortState = {
  host: string;
  port: number | null;
  defaultPort: number;
  existingProcess: string | null;
  execOptions: ExecSyncOptionsWithStringEncoding;
};

type CodegenState = {
  chunkNameCache: Map<string, string>;
  chunkNameCount: Map<string, number>;
  routesCode: RoutesCode;
  generatedFilesDir: string;
  routes: PluginRouteConfig[];
  baseUrl: string;
};

type RouteSlashState = {
  routesToSort: RouteConfig[];
  baseUrl: string;
  trailingSlashParams: ApplyTrailingSlashParams | null;
};

type HtmlTagState = {
  plugins: LoadedPlugin[];
  headTags: string;
  preBodyTags: string;
  postBodyTags: string;
  lastTag: HtmlTagObject | null;
  lastMarkup: string;
};

class SiteOrchestrator {
  private brokenLinkState: BrokenLinkState = {
    collectedLinks: new Map(),
    validPathnames: new Set(),
    remainingRoutes: [],
    routes: [],
    brokenLinks: {},
    brokenPaths: {},
    brokenAnchors: {},
    onBrokenLinks: 'throw',
    onBrokenAnchors: 'warn',
  };

  private configState: ConfigState = {
    defaultI18nConfig: {
      defaultLocale: 'en',
      path: DEFAULT_I18N_DIR_NAME,
      locales: ['en'],
      localeConfigs: {},
    },
    defaultStorageConfig: {
      type: 'localStorage',
      namespace: false,
    },
    defaultFutureConfig: {
      experimental_storage: {
        type: 'localStorage',
        namespace: false,
      },
    },
    defaultMarkdownConfig: {
      format: 'mdx',
      mermaid: false,
      preprocessor: undefined,
      parseFrontMatter: DEFAULT_PARSE_FRONT_MATTER,
      mdx1Compat: {
        comments: true,
        admonitions: true,
        headingIds: true,
      },
      anchors: {
        maintainCase: false,
      },
      remarkRehypeOptions: undefined,
    },
    defaultConfig: {
      i18n: {
        defaultLocale: 'en',
        path: DEFAULT_I18N_DIR_NAME,
        locales: ['en'],
        localeConfigs: {},
      },
      future: {
        experimental_storage: {
          type: 'localStorage',
          namespace: false,
        },
      },
      onBrokenLinks: 'throw',
      onBrokenAnchors: 'warn',
      onBrokenMarkdownLinks: 'warn',
      onDuplicateRoutes: 'warn',
      plugins: [],
      themes: [],
      presets: [],
      headTags: [],
      stylesheets: [],
      scripts: [],
      clientModules: [],
      customFields: {},
      themeConfig: {},
      titleDelimiter: '|',
      noIndex: false,
      tagline: '',
      baseUrlIssueBanner: true,
      staticDirectories: [DEFAULT_STATIC_DIR_NAME],
      markdown: {
        format: 'mdx',
        mermaid: false,
        preprocessor: undefined,
        parseFrontMatter: DEFAULT_PARSE_FRONT_MATTER,
        mdx1Compat: {
          comments: true,
          admonitions: true,
          headingIds: true,
        },
        anchors: {
          maintainCase: false,
        },
        remarkRehypeOptions: undefined,
      },
    },
    pluginSchema: undefined,
    themeSchema: undefined,
    presetSchema: undefined,
    localeConfigSchema: undefined,
    i18nConfigSchema: undefined,
    storageConfigSchema: undefined,
    futureConfigSchema: undefined,
    siteUrlSchema: undefined,
    configSchema: Joi.object(),
    siteConfigPath: '',
    lastValidatedConfig: null,
    unknownFields: '',
    formattedError: '',
  };

  private hostPortState: HostPortState = {
    host: 'localhost',
    port: null,
    defaultPort: DEFAULT_PORT,
    existingProcess: null,
    execOptions: {
      encoding: 'utf8',
      stdio: [/* stdin */ 'pipe', /* stdout */ 'pipe', /* stderr */ 'ignore'],
    },
  };

  private codegenState: CodegenState = {
    chunkNameCache: new Map(),
    chunkNameCount: new Map(),
    routesCode: {
      routesConfig: '',
      routesChunkNames: {},
      registry: {},
    },
    generatedFilesDir: '',
    routes: [],
    baseUrl: '/',
  };

  private routeSlashState: RouteSlashState = {
    routesToSort: [],
    baseUrl: '/',
    trailingSlashParams: null,
  };

  private htmlTagState: HtmlTagState = {
    plugins: [],
    headTags: '',
    preBodyTags: '',
    postBodyTags: '',
    lastTag: null,
    lastMarkup: '',
  };

  private schemasInitialized = this.buildAllConfigSchemas();

  get defaultI18nConfig(): I18nConfig {
    return this.configState.defaultI18nConfig;
  }

  get defaultStorageConfig(): StorageConfig {
    return this.configState.defaultStorageConfig;
  }

  get defaultFutureConfig(): FutureConfig {
    return this.configState.defaultFutureConfig;
  }

  get defaultMarkdownConfig(): MarkdownConfig {
    return this.configState.defaultMarkdownConfig;
  }

  get defaultConfig(): ConfigState['defaultConfig'] {
    return this.configState.defaultConfig;
  }

  get configSchema(): ConfigState['configSchema'] {
    return this.configState.configSchema;
  }

  brokenLinkMessage(brokenLink: BrokenLink): string {
    const showResolvedLink = brokenLink.link !== brokenLink.resolvedLink;
    return `${brokenLink.link}${
      showResolvedLink ? ` (resolved as: ${brokenLink.resolvedLink})` : ''
    }`;
  }

  indent(str: string): string {
    return `  ${str.replace(/\n/g, `\n  `)}`;
  }

  isModule(value: unknown): value is Module {
    return (
      typeof value === 'string' ||
      (typeof value === 'object' &&
        // eslint-disable-next-line no-underscore-dangle
        !!(value as {[key: string]: unknown} | null)?.__import)
    );
  }

  getModulePath(target: Module): string {
    if (typeof target === 'string') {
      return target;
    }
    const queryStr = target.query ? `?${query.stringify(target.query)}` : '';
    return `${target.path}${queryStr}`;
  }

  serializeRouteConfig({
    routePath,
    routeHash,
    exact,
    subroutesCodeStrings,
    attributes,
  }: {
    routePath: string;
    routeHash: string;
    exact?: boolean;
    subroutesCodeStrings?: string[];
    attributes: {[attributeName: string]: unknown};
  }): string {
    const parts = [
      `path: '${routePath}'`,
      `component: ComponentCreator('${routePath}', '${routeHash}')`,
    ];

    if (exact) {
      parts.push(`exact: true`);
    }

    if (subroutesCodeStrings) {
      parts.push(
        `routes: [
${this.indent(subroutesCodeStrings.join(',\n'))}
]`,
      );
    }

    Object.entries(attributes).forEach(([attrName, attrValue]) => {
      const isIdentifier =
        /^[$_\p{ID_Start}][$\u200c\u200d\p{ID_Continue}]*$/u.test(attrName);
      const key = isIdentifier ? attrName : JSON.stringify(attrName);
      parts.push(`${key}: ${JSON.stringify(attrValue)}`);
    });

    return `{
${this.indent(parts.join(',\n'))}
}`;
  }

  ensureNoPropsConflict(route: RouteConfig): void {
    if (!route.props && !route.modules) {
      return;
    }
    const conflictingPropNames = _.intersection(
      Object.keys(route.props ?? {}),
      Object.keys(route.modules ?? {}),
    );
    if (conflictingPropNames.length > 0) {
      throw new Error(
        `Route ${
          route.path
        } has conflicting props declared using both route.modules and route.props APIs for keys: ${conflictingPropNames.join(
          ', ',
        )}\nThis is not permitted, otherwise one prop would override the over.`,
      );
    }
  }

  clearConsole(): void {
    process.stdout.write(
      process.platform === 'win32' ? '\x1B[2J\x1B[0f' : '\x1B[2J\x1B[3J\x1B[H',
    );
  }

  filterIntermediateRoutes(routesInput: RouteConfig[]): RouteConfig[] {
    const routesWithout404 = routesInput.filter((route) => route.path !== '*');
    const flattened = flattenRoutes(routesWithout404);
    this.brokenLinkState.routes = flattened;
    return flattened;
  }

  normalizeCollectedLinks(
    collectedLinks: CollectedLinks,
  ): CollectedLinksNormalized {
    const result: CollectedLinksNormalized = new Map();
    Object.entries(collectedLinks).forEach(([pathname, pageCollectedData]) => {
      result.set(pathname, {
        links: new Set(pageCollectedData.links.filter(_.isString)),
        anchors: new Set(
          pageCollectedData.anchors
            .filter(_.isString)
            .map((anchor) => (anchor.startsWith('#') ? anchor.slice(1) : anchor)),
        ),
      });
    });
    this.brokenLinkState.collectedLinks = result;
    return result;
  }

  prepareBrokenLinkState({
    collectedLinks,
    routes,
  }: {
    collectedLinks: CollectedLinksNormalized;
    routes: RouteConfig[];
  }): void {
    this.brokenLinkState.collectedLinks = collectedLinks;
    this.brokenLinkState.routes = routes;
    this.brokenLinkState.validPathnames = new Set(collectedLinks.keys());

    const disableOptimization = false;
    if (disableOptimization) {
      this.brokenLinkState.remainingRoutes = routes;
      return;
    }
    const [validPathnameRoutes, otherRoutes] = _.partition(
      routes,
      (route) =>
        route.exact && this.brokenLinkState.validPathnames.has(route.path),
    );
    validPathnameRoutes.forEach((validPathnameRoute) => {
      if (!validPathnameRoute.strict) {
        this.brokenLinkState.validPathnames.add(
          addTrailingSlash(validPathnameRoute.path),
        );
        this.brokenLinkState.validPathnames.add(
          removeTrailingSlash(validPathnameRoute.path),
        );
      }
    });
    this.brokenLinkState.remainingRoutes = otherRoutes;
  }

  isPathnameMatchingAnyRoute(pathname: string): boolean {
    if (matchRoutes(this.brokenLinkState.remainingRoutes, pathname).length > 0) {
      this.brokenLinkState.validPathnames.add(pathname);
      return true;
    }
    return false;
  }

  isPathBrokenLink(linkPath: URLPath): boolean {
    const pathnames = [linkPath.pathname, decodeURI(linkPath.pathname)];
    if (pathnames.some((p) => this.brokenLinkState.validPathnames.has(p))) {
      return false;
    }
    if (pathnames.some((p) => this.isPathnameMatchingAnyRoute(p))) {
      return false;
    }
    return true;
  }

  isAnchorBrokenLink(linkPath: URLPath) {
    const collectedLinks = this.brokenLinkState.collectedLinks;
    const {pathname, hash} = linkPath;
    // Link has no hash: it can't be a broken anchor link
    if (hash === undefined) {
      return false;
    }
    // Link has empty hash ("#", "/page#"...): we do not report it as broken
    // Empty hashes are used for various weird reasons, by us and other users...
    // See for example: https://github.com/facebook/docusaurus/pull/6003
    if (hash === '') {
      return false;
    }
    const targetPage =
      collectedLinks.get(pathname) || collectedLinks.get(decodeURI(pathname));
    // link with anchor to a page that does not exist (or did not collect any
    // link/anchor) is considered as a broken anchor
    if (!targetPage) {
      return true;
    }
    // it's a not broken anchor if the anchor exists on the target page
    if (
      targetPage.anchors.has(hash) ||
      targetPage.anchors.has(decodeURIComponent(hash))
    ) {
      return false;
    }
    return true;
  }

  getBrokenLinksForPage(pagePath: string): BrokenLink[] {
    const pageData = this.brokenLinkState.collectedLinks.get(pagePath)!;
    const brokenLinks: BrokenLink[] = [];

    pageData.links.forEach((link) => {
      const linkPath = parseURLPath(link, pagePath);
      if (this.isPathBrokenLink(linkPath)) {
        brokenLinks.push({
          link,
          resolvedLink: serializeURLPath(linkPath),
          anchor: false,
        });
      } else if (this.isAnchorBrokenLink(linkPath)) {
        brokenLinks.push({
          link,
          resolvedLink: serializeURLPath(linkPath),
          anchor: true,
        });
      }
    });

    return brokenLinks;
  }

  collectBrokenLinks(): BrokenLinksMap {
    const result: BrokenLinksMap = {};
    this.brokenLinkState.collectedLinks.forEach((_unused, pagePath) => {
      try {
        result[pagePath] = this.getBrokenLinksForPage(pagePath);
      } catch (e) {
        throw new Error(`Unable to get broken links for page ${pagePath}.`, {
          cause: e,
        });
      }
    });
    this.brokenLinkState.brokenLinks = result;
    return result;
  }

  createBrokenLinksMessage(
    pagePath: string,
    brokenLinks: BrokenLink[],
  ): string {
    const linksForPage =
      brokenLinks.length > 0
        ? brokenLinks
        : this.brokenLinkState.brokenLinks[pagePath] ?? [];
    const type = linksForPage[0]?.anchor === true ? 'anchor' : 'link';
    const anchorMessage =
      linksForPage.length > 0
        ? `- Broken ${type} on source page path = ${pagePath}:
   -> linking to ${linksForPage
     .map((item) => this.brokenLinkMessage(item))
     .join('\n   -> linking to ')}`
        : '';
    return `${anchorMessage}`;
  }

  getFrequentBrokenLinksMessage(brokenPathsMap: BrokenLinksMap): string {
    const sourceMap =
      Object.keys(brokenPathsMap).length > 0
        ? brokenPathsMap
        : this.brokenLinkState.brokenPaths;
    const flatList = Object.entries(sourceMap).flatMap(
      ([pagePath, brokenLinks]) =>
        brokenLinks.map((brokenLink) => ({pagePath, brokenLink})),
    );

    const countedBrokenLinks = _.countBy(
      flatList,
      (item) => item.brokenLink.link,
    );

    const FrequencyThreshold = 5;
    const frequentLinks = Object.entries(countedBrokenLinks)
      .filter(([, count]) => count >= FrequencyThreshold)
      .map(([link]) => link);

    if (frequentLinks.length === 0) {
      return '';
    }

    return logger.interpolate`

It looks like some of the broken links we found appear in many pages of your site.
Maybe those broken links appear on all pages through your site layout?
We recommend that you check your theme configuration for such links (particularly, theme navbar and footer).
Frequent broken links are linking to:${frequentLinks}`;
  }

  createBrokenAnchorsMessage(brokenAnchors: BrokenLinksMap): string | undefined {
    const anchorsToReport =
      Object.keys(brokenAnchors).length > 0
        ? brokenAnchors
        : this.brokenLinkState.brokenAnchors;
    if (Object.keys(anchorsToReport).length === 0) {
      return undefined;
    }

    return `Docusaurus found broken anchors!

Please check the pages of your site in the list below, and make sure you don't reference any anchor that does not exist.
Note: it's possible to ignore broken anchors with the 'onBrokenAnchors' Docusaurus configuration, and let the build pass.

Exhaustive list of all broken anchors found:
${Object.entries(anchorsToReport)
  .map(([pagePath, brokenAnchorsForPage]) =>
    this.createBrokenLinksMessage(pagePath, brokenAnchorsForPage),
  )
  .join('\n')}
`;
  }

  createBrokenPathsMessage(brokenPathsMap: BrokenLinksMap): string | undefined {
    const pathsToReport =
      Object.keys(brokenPathsMap).length > 0
        ? brokenPathsMap
        : this.brokenLinkState.brokenPaths;
    if (Object.keys(pathsToReport).length === 0) {
      return undefined;
    }

    return `Docusaurus found broken links!

Please check the pages of your site in the list below, and make sure you don't reference any path that does not exist.
Note: it's possible to ignore broken links with the 'onBrokenLinks' Docusaurus configuration, and let the build pass.${this.getFrequentBrokenLinksMessage(
      pathsToReport,
    )}

Exhaustive list of all broken links found:
${Object.entries(pathsToReport)
  .map(([pagePath, brokenPaths]) =>
    this.createBrokenLinksMessage(pagePath, brokenPaths),
  )
  .join('\n')}
`;
  }

  splitBrokenLinks(): {brokenPaths: BrokenLinksMap; brokenAnchors: BrokenLinksMap} {
    const brokenPaths: BrokenLinksMap = {};
    const brokenAnchors: BrokenLinksMap = {};

    Object.entries(this.brokenLinkState.brokenLinks).forEach(
      ([pathname, pageBrokenLinks]) => {
        const [anchorBrokenLinks, pathBrokenLinks] = _.partition(
          pageBrokenLinks,
          (link) => link.anchor,
        );

        if (pathBrokenLinks.length > 0) {
          brokenPaths[pathname] = pathBrokenLinks;
        }
        if (anchorBrokenLinks.length > 0) {
          brokenAnchors[pathname] = anchorBrokenLinks;
        }
      },
    );

    this.brokenLinkState.brokenPaths = brokenPaths;
    this.brokenLinkState.brokenAnchors = brokenAnchors;
    return {brokenPaths, brokenAnchors};
  }

  reportBrokenLinks(): void {
    const {brokenPaths, brokenAnchors} = this.splitBrokenLinks();

    const pathErrorMessage = this.createBrokenPathsMessage(brokenPaths);
    if (pathErrorMessage) {
      logger.report(this.brokenLinkState.onBrokenLinks)(pathErrorMessage);
    }

    const anchorErrorMessage = this.createBrokenAnchorsMessage(brokenAnchors);
    if (anchorErrorMessage) {
      logger.report(this.brokenLinkState.onBrokenAnchors)(anchorErrorMessage);
    }
  }

  async handleBrokenLinks({
    collectedLinks,
    onBrokenLinks,
    onBrokenAnchors,
    routes,
  }: {
    collectedLinks: CollectedLinks;
    onBrokenLinks: ReportingSeverity;
    onBrokenAnchors: ReportingSeverity;
    routes: RouteConfig[];
  }): Promise<void> {
    this.brokenLinkState.onBrokenLinks = onBrokenLinks;
    this.brokenLinkState.onBrokenAnchors = onBrokenAnchors;
    if (onBrokenLinks === 'ignore' && onBrokenAnchors === 'ignore') {
      return;
    }
    const normalized = this.normalizeCollectedLinks(collectedLinks);
    const filteredRoutes = this.filterIntermediateRoutes(routes);
    this.prepareBrokenLinkState({
      collectedLinks: normalized,
      routes: filteredRoutes,
    });
    this.collectBrokenLinks();
    this.reportBrokenLinks();
  }

  createPluginSchema(theme: boolean): unknown {
    const schema = Joi.alternatives()
      .try(
        Joi.function(),
        Joi.array()
          .ordered(Joi.function().required(), Joi.object().required())
          .length(2),
        Joi.string(),
        Joi.array()
          .ordered(Joi.string().required(), Joi.object().required())
          .length(2),
        Joi.any().valid(false, null),
      )
      // @ts-expect-error: bad lib def, doesn't recognize an array of reports
      .error((errors) => {
        errors.forEach((error) => {
          const validConfigExample = theme
            ? `Example valid theme config:
{
  themes: [
    ["@docusaurus/theme-classic",options],
    "./myTheme",
    ["./myTheme",{someOption: 42}],
    function myTheme() { },
    [function myTheme() { },options]
  ],
};`
            : `Example valid plugin config:
{
  plugins: [
    ["@docusaurus/plugin-content-docs",options],
    "./myPlugin",
    ["./myPlugin",{someOption: 42}],
    function myPlugin() { },
    [function myPlugin() { },options]
  ],
};`;

          error.message = ` => Bad Docusaurus ${
            theme ? 'theme' : 'plugin'
          } value ${error.path.reduce((acc, cur) =>
            typeof cur === 'string' ? `${acc}.${cur}` : `${acc}[${cur}]`,
          )}.
${validConfigExample}
`;
        });
        return errors;
      });
    if (theme) {
      this.configState.themeSchema = schema;
    } else {
      this.configState.pluginSchema = schema;
    }
    return schema;
  }

  createThemeSchema(): unknown {
    const schema = this.createPluginSchema(true);
    this.configState.themeSchema = schema;
    return schema;
  }

  createPresetSchema(): unknown {
    const schema = Joi.alternatives()
      .try(
        Joi.string(),
        Joi.array()
          .items(Joi.string().required(), Joi.object().required())
          .length(2),
        Joi.any().valid(false, null),
      )
      .messages({
        'alternatives.types': `{#label} does not look like a valid preset config. A preset config entry should be one of:
- A tuple of [presetName, options], like \`["classic", \\{ blog: false \\}]\`, or
- A simple string, like \`"classic"\``,
      });
    this.configState.presetSchema = schema;
    return schema;
  }

  buildLocaleConfigSchema(): unknown {
    const schema = Joi.object({
      label: Joi.string(),
      htmlLang: Joi.string(),
      direction: Joi.string().equal('ltr', 'rtl').default('ltr'),
      calendar: Joi.string(),
      path: Joi.string(),
    });
    this.configState.localeConfigSchema = schema;
    return schema;
  }

  buildI18nConfigSchema(): unknown {
    const schema = Joi.object<I18nConfig>({
      defaultLocale: Joi.string().required(),
      path: Joi.string().default(this.configState.defaultI18nConfig.path),
      locales: Joi.array()
        .items()
        .min(1)
        .items(Joi.string().required())
        .required(),
      localeConfigs: Joi.object()
        .pattern(/.*/, this.buildLocaleConfigSchema())
        .default(this.configState.defaultI18nConfig.localeConfigs),
    })
      .optional()
      .default(this.configState.defaultI18nConfig);
    this.configState.i18nConfigSchema = schema;
    return schema;
