  buildStorageConfigSchema(): unknown {
    const schema = Joi.object({
      type: Joi.string()
        .equal('localStorage', 'sessionStorage')
        .default(this.configState.defaultStorageConfig.type),
      namespace: Joi.alternatives()
        .try(Joi.string(), Joi.boolean())
        .default(this.configState.defaultStorageConfig.namespace),
